      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูดีดทำนองเพลงสั้นๆ บนคาลิมบ้าคีย์ C Major เปรียบเทียบ 2 แบบ: แบบที่ 1 ดีดโน้ตเดี่ยวทีละตัว (แบบ ม.1) และแบบที่ 2 ดีดเติมคู่เสียงประสาน 2 นิ้วโป้งพร้อมกัน (แบบ ม.2) 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'ทำไมการดีดเพิ่มอีกเพียง 1 นิ้วโป้งในคีย์ C Major เดิม ถึงทำให้เสียงคาลิมบ้าฟังดูอิ่มกังวานเหมือนมีนักดนตรีเล่นพร้อมกัน 2 คน?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
