    "teach": {
     "title": "ขั้นสอน",
     "minutes": 36,
     "tag": "P - Practice (18 นาที) / A - Active Collaboration & Analysis (10 นาที) / C - Creative Challenge (8 นาที)",
     "items": [
      "2.1 การสาธิตจำลองทักษะและการดีดไร้เสียง (Modeling & Silent Air-Tap): • ครูสาธิตแบบอย่างท่าทางการวางมือประคองเครื่องทำมุม 45 องศา และการดีดลิ่มเสียงตามจังหวะเคาะ นักเรียนทำตามแบบจำลองไร้เสียง (Silent Air-Tap) เพื่อสร้างความคุ้นเคยของกล้ามเนื้อมือและประสาทสัมผัส 2.2 วงจรฝึกปฏิบัติปรับเหมาะ 3 ระดับ (3-Tier Differentiated Mastery Practice): นักเรียนทบทวนการไล่บันไดเสียง C Major และฝึกดีดคู่เสียงประสาน (Dyads) ตามวงจรการเรียนรู้ปรับเหมาะ 3 ระดับ (3-Tier Mastery Loop): • 🥉 ระดับพื้นฐาน (Bronze — Foundation): ทบทวนไล่สเกล C Major ขาขึ้น-ขาลง และดีดคู่เสียงประสานขั้นคู่ 3 พื้นฐาน (1-3 [โด-มี], 2-4 [เร-ฟา], 3-5 [มี-ซอล]) ที่ความเร็ว 60 BPM ความถูกต้องไม่น้อยกว่าร้อยละ 80 • 🥈 ระดับมาตรฐาน (Silver — Core Standard): ดีดไล่คู่เสียงประสานขั้นคู่ 3 ครบทั้งบันไดเสียง C Major (1-3, 2-4, 3-5, 4-6, 5-7, 6-1') และขั้นคู่ 5 (1-5 [โด-ซอล]) พร้อมร้องโน้ต Solfege เสียงบนประกอบได้อย่างแม่นยำ • 🥇 ระดับท้าทาย (Gold — Advanced Extension): บรรเลงทำนองเพลงสั้นในคีย์ C Major โดยสอดแทรกการดีดคู่เสียงประสานในจังหวะตก (Beat 1 และ Beat 3) ได้อย่างพริ้วไหวและกังวาน 2.3 การล็อกความเร็วและจังหวะเคาะ (Pulse & Tempo Synchronization): • ครูทำหน้าที่สังเกตการณ์เชิงรุก (Active Observation) ให้คำชี้แนะรายบุคคล (Individual Scaffolding) เพื่อให้นักเรียนรักษาความเร็วสม่ำเสมอตามจังหวะบีตมาตรฐาน",
      "3.1 การจัดคู่หูดนตรีร่วมบรรเลง (Buddy Co-Pilot Setup): • นักเรียนจับคู่ 20 คู่ (ทุกคนมีเครื่องประจำตัว 1:1) แบ่งบทบาทระหว่าง Melody Lead (ผู้บรรเลงหลัก) และ Rhythm Coach (ผู้คุมจังหวะและคอยเคาะช่วย) 3.2 การบรรเลงประสานและการวิเคราะห์ความแม่นยำ (Synchronized Rehearsal & Rhythm Check): • กิจกรรมคู่บัดดี้ (Buddy Acoustic Check): สลับบทบาทเป็น Performer และ Acoustic Coach (คนละ 5 นาที) ตรวจสอบว่าเล็บนิ้วโป้งซ้ายและขวาดีดลิ่มเสียงลงพร้อมกันสนิท (ไม่เกิดเสียงเหลื่อม Flam) และบันทึกผลลงในใบกิจกรรม ผ01 3.3 การแลกเปลี่ยนฟีดแบ็กเชิงสร้างสรรค์ (Constructive Peer Feedback): • สลับบทบาทหน้าที่ และร่วมกันบันทึกจุดที่จังหวะยังแกว่งหรือสะดุดลงในใบกิจกรรมประจำแผน",
      "4.1 การมอบหมายภารกิจสร้างสรรค์ทางดนตรี (Creative Challenge Briefing): • ภารกิจ 'C-Major Harmonic Phrase Design': คู่บัดดี้ร่วมกันสร้างสรรค์วลีเพลงสั้น 4 ห้องเพลงในคีย์ C Major โดยเลือกเติมคู่เสียงประสานขั้นคู่ 3 หรือคู่ 5 ลงในจังหวะสำคัญ พร้อมตั้งชื่อวลีเพลงและบันทึกลงในใบกิจกรรม ผ01 4.2 การรังสรรค์และทดลองบรรเลง (Inventive Rehearsal & Tryout): • คู่หูดนตรีร่วมกันออกแบบ ค้นคว้าแพทเทิร์นเสียง และทดลองบรรเลงในคีย์ C Major อย่างอิสระ"
     ]
    },
