      "2.1 การสาธิตจำลองทักษะและการดีดไร้เสียง (Modeling & Silent Air-Tap): • ครูสาธิตแบบอย่างท่าทางการวางมือประคองเครื่องทำมุม 45 องศา และการดีดลิ่มเสียงตามจังหวะเคาะ นักเรียนทำตามแบบจำลองไร้เสียง (Silent Air-Tap) เพื่อสร้างความคุ้นเคยของกล้ามเนื้อมือและประสาทสัมผัส 2.2 วงจรฝึกปฏิบัติปรับเหมาะ 3 ระดับ (3-Tier Differentiated Mastery Practice): นักเรียนศึกษาบทเรียนเครื่องหมายแปลงเสียง (#, b, ♮) บนผังลิ่มคีย์บอร์ดกระดาษและฝึกปฏิบัติตามวงจร 3-Tier Mastery Loop: • 🥉 ระดับพื้นฐาน (Bronze — Foundation): อ่านและเขียนสัญลักษณ์ #, b, ♮ บนบรรทัด 5 เส้นและโน้ตไทย พร้อมชี้ตำแหน่งเสียงที่สูงขึ้น/ต่ำลงครึ่งเสียงบนผังลิ่มคีย์บอร์ดจำลองในใบกิจกรรม ผ02 ได้ถูกต้องร้อยละ 80 ขึ้นไป • 🥈 ระดับมาตรฐาน (Silver — Core Standard): ขับร้องโน้ต Solfege เทียบเสียงปกติกับเสียงที่ติดเครื่องหมายแปลงเสียงตามเสียงคีย์บอร์ดครู (เช่น ฟา -> ฟาชาร์ป -> ซอล) และจำแนกโน้ตที่ติด #/b ในบทเพลงตัวอย่างได้ถูกต้อง • 🥇 ระดับท้าทาย (Gold — Advanced Extension): คำนวณระยะขั้นคู่เสียงเพื่อย้ายคีย์ (Transpose) วลีเพลงสั้นจากคีย์ G Major (ที่มี F#) และ F Major (ที่มี Bb) ให้กลับมาเป็นโน้ตในคีย์ C Major ล้วนได้สำเร็จ 2.3 การล็อกความเร็วและจังหวะเคาะ (Pulse & Tempo Synchronization): • ครูทำหน้าที่สังเกตการณ์เชิงรุก (Active Observation) ให้คำชี้แนะรายบุคคล (Individual Scaffolding) เพื่อให้นักเรียนรักษาความเร็วสม่ำเสมอตามจังหวะบีตมาตรฐาน",
      "3.1 การจัดคู่หูดนตรีร่วมบรรเลง (Buddy Co-Pilot Setup): • นักเรียนจับคู่ 20 คู่ (ทุกคนมีเครื่องประจำตัว 1:1) แบ่งบทบาทระหว่าง Melody Lead (ผู้บรรเลงหลัก) และ Rhythm Coach (ผู้คุมจังหวะและคอยเคาะช่วย) 3.2 การบรรเลงประสานและการวิเคราะห์ความแม่นยำ (Synchronized Rehearsal & Rhythm Check): • กิจกรรมคู่บัดดี้ 'Accidental Codebreaker': ร่วมกันตรวจสอบความถูกต้องของการอ่าน-เขียนโน้ตที่มีเครื่องหมาย #, b, ♮ ทั้งระบบโน้ตสากลและโน้ตไทย (เช่น ฟ# / ทb) ลงในตารางใบกิจกรรม ผ02 3.3 การแลกเปลี่ยนฟีดแบ็กเชิงสร้างสรรค์ (Constructive Peer Feedback): • สลับบทบาทหน้าที่ และร่วมกันบันทึกจุดที่จังหวะยังแกว่งหรือสะดุดลงในใบกิจกรรมประจำแผน",
      "4.1 การมอบหมายภารกิจสร้างสรรค์ทางดนตรี (Creative Challenge Briefing): • ภารกิจชิ้นงาน 'Transposition to C-Major Studio': คู่บัดดี้แปลงโน้ตเพลงสั้น 4 ห้องจากคีย์ G Major (D-E-F#-G) ให้เป็นคีย์ C Major (G-A-B-C หรือ C-D-E-F) ลงในใบงาน แล้วทดลองดีดโน้ตที่แปลงเป็นคีย์ C แล้วบนคาลิมบ้าเพื่อพิสูจน์ว่าทำนองยังคงไพเราะเหมือนเดิมทุกประการ! 4.2 การรังสรรค์และทดลองบรรเลง (Inventive Rehearsal & Tryout): • คู่หูดนตรีร่วมกันออกแบบ ค้นคว้าแพทเทิร์นเสียง และทดลองบรรเลงในคีย์ C Major อย่างอิสระ"
