      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูจำลองสถานการณ์วงดนตรีที่พาร์ทที่ 2 เข้าเพลงวนช้าไปครึ่งจังหวะทำให้เสียงชนกันทั้งเพลง 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'เมื่อพาร์ทที่ 2 เข้าเพลงวนผิดจังหวะ การสั่งให้เริ่มเล่นใหม่ตั้งแต่ต้นเพลงช่วยแก้ปัญหาได้จริงหรือ? เราควรใช้เทคนิคเจาะซ้อมเฉพาะห้องรอยต่ออย่างไร?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
