    "teach": {
     "title": "ขั้นสอน",
     "minutes": 37,
     "tag": "P - Practice (15 นาที) / A - Active Collaboration & Analysis (14 นาที) / C - Creative Challenge (8 นาที)",
     "items": [
      "2.1 การสาธิตจำลองทักษะและการดีดไร้เสียง (Modeling & Silent Air-Tap): • ครูสาธิตแบบอย่างท่าทางการวางมือประคองเครื่องทำมุม 45 องศา และการดีดลิ่มเสียงตามจังหวะเคาะ นักเรียนทำตามแบบจำลองไร้เสียง (Silent Air-Tap) เพื่อสร้างความคุ้นเคยของกล้ามเนื้อมือและประสาทสัมผัส 2.2 วงจรฝึกปฏิบัติปรับเหมาะ 3 ระดับ (3-Tier Differentiated Mastery Practice): แต่ละวงกำหนดเป้าหมายการซ้อม (Micro-Goal) และฝึกซ้อมตามวงจร 3-Tier Mastery Loop: • 🥉 ระดับพื้นฐาน (Bronze — Foundation): แยกซ้อมพาร์ทของตนเอง (Canon 1 / Canon 2 / คอร์ด C-Am-F-G) ที่ความเร็ว 60 BPM ความถูกต้อง ≥ 80% • 🥈 ระดับมาตรฐาน (Silver — Core Standard): รวมวงซ้อมเชื่อมต่อท่อน A เข้าสู่ท่อนเพลงวน Canon ที่ 70 BPM โดยพาร์ทที่ 2 เข้าตรงจังหวะไม่คลาดเคลื่อน • 🥇 ระดับท้าทาย (Gold — Advanced Extension): บรรเลงเพลงวนพร้อมควบคุมน้ำหนักเสียงให้พาร์ทที่เพิ่งเข้าใหม่โดดเด่นขึ้นอย่างชัดเจน 2.3 การล็อกความเร็วและจังหวะเคาะ (Pulse & Tempo Synchronization): • ครูทำหน้าที่สังเกตการณ์เชิงรุก (Active Observation) ให้คำชี้แนะรายบุคคล (Individual Scaffolding) เพื่อให้นักเรียนรักษาความเร็วสม่ำเสมอตามจังหวะบีตมาตรฐาน",
      "3.1 การจัดคู่หูดนตรีร่วมบรรเลง (Buddy Co-Pilot Setup): • นักเรียนจับคู่ 20 คู่ (ทุกคนมีเครื่องประจำตัว 1:1) แบ่งบทบาทระหว่าง Melody Lead (ผู้บรรเลงหลัก) และ Rhythm Coach (ผู้คุมจังหวะและคอยเคาะช่วย) 3.2 การบรรเลงประสานและการวิเคราะห์ความแม่นยำ (Synchronized Rehearsal & Rhythm Check): • สมาชิกทั้ง 5 คนร่วมกันวินิจฉัยหา 'ห้องเพลงที่เป็นคอขวด (Bottleneck Measures)' และใช้เทคนิค Slow-Tempo Looping ซ้อมวนเฉพาะ 4 ห้องรอยต่อนั้นซ้ำ 5 รอบจนผ่านเกณฑ์ร้อยละ 80 3.3 การแลกเปลี่ยนฟีดแบ็กเชิงสร้างสรรค์ (Constructive Peer Feedback): • สลับบทบาทหน้าที่ และร่วมกันบันทึกจุดที่จังหวะยังแกว่งหรือสะดุดลงในใบกิจกรรมประจำแผน",
      "4.1 การมอบหมายภารกิจสร้างสรรค์ทางดนตรี (Creative Challenge Briefing): • ภารกิจ 'Dynamic Phrasing for Canon': แต่ละวงออกแบบแผนผังความดัง-เบา (เช่น เมื่อพาร์ท 2 เริ่มเข้าด้วยความดัง mf ให้พาร์ท 1 ลดความดังลงเหลือ p เพื่อให้ผู้ฟังได้ยินพาร์ทเข้าใหม่ชัดเจน) บันทึกลงในใบกิจกรรม ผ07 4.2 การรังสรรค์และทดลองบรรเลง (Inventive Rehearsal & Tryout): • คู่หูดนตรีร่วมกันออกแบบ ค้นคว้าแพทเทิร์นเสียง และทดลองบรรเลงในคีย์ C Major อย่างอิสระ"
     ]
    },
