      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูเปิดตัวอย่างเสียงวงคาลิมบ้า 2 คลิป: คลิปแรกพาร์ทคอร์ดรูดเสียงดังกลบแนวเพลงวนจนฟังไม่ออก คลิปที่สองจัดวางตำแหน่งซ้าย-ขวาและแบ่งระดับความดังอย่างมีมิติ 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'ในเมื่อคาลิมบ้าทุกเครื่องหน้าตาเหมือนกันหมด เราจะจัดตำแหน่งการยืนและควบคุมแรงกดนิ้วอย่างไร ให้ผู้ชมแยกแยะเสียงพาร์ทที่ 1 พาร์ทที่ 2 และเสียงคอร์ดได้ชัดเจนราวกับฟังระบบ Stereo?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
