      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูชี้แจงลำดับการแสดงของกลุ่มที่ 1–4 ทบทวนกติกามารยาทผู้ชมคอนเสิร์ตสากล 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'นักวิจารณ์ดนตรีมืออาชีพแตกต่างจากผู้ฟังทั่วไปอย่างไร และเราจะเขียนคำแนะนำอย่างไรให้เพื่อนนำไปพัฒนาวงได้จริงโดยไม่เสียกำลังใจ?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
