      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูชื่นชมภาพรวมจากคาบที่แล้วและสร้างพลังใจให้กลุ่มที่ 5–8 ก่อนขึ้นเวที 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'หลังจากผ่านการซ้อมและขึ้นแสดงจริง ทักษะทางดนตรีและการทำงานร่วมกับผู้อื่นในตัวเราเปลี่ยนแปลงไปจากวันแรกอย่างไรบ้าง?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
