      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูเปิดตัวอย่างเสียงดนตรี 3 วัฒนธรรม (1. วงสะล้อซอซึงล้านนา 2. ดนตรีบรรเลงกู่เจิง/เอเชียตะวันออก 3. วงออร์เคสตราสากล) 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'แม้ไม่มีเนื้อร้องแม้แต่คำเดียว ทำไมสมองของเราถึงบอกได้ทันทีว่าเพลงไหนเป็นดนตรีล้านนา/เอเชีย และเพลงไหนเป็นดนตรีตะวันตก? ความลับซ่อนอยู่ที่ลิ่มเสียงตัวไหน?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
