     "items": [
      "2.1 การสาธิตจำลองทักษะและการดีดไร้เสียง (Modeling & Silent Air-Tap): • ครูสาธิตแบบอย่างท่าทางการวางมือประคองเครื่องทำมุม 45 องศา และการดีดลิ่มเสียงตามจังหวะเคาะ นักเรียนทำตามแบบจำลองไร้เสียง (Silent Air-Tap) เพื่อสร้างความคุ้นเคยของกล้ามเนื้อมือและประสาทสัมผัส 2.2 วงจรฝึกปฏิบัติปรับเหมาะ 3 ระดับ (3-Tier Differentiated Mastery Practice): นักเรียนสำรวจสายอาชีพทางดนตรีและบทบาทในธุรกิจบันเทิง (ศ 2.1 ม.2/7) ตามวงจร 3-Tier Mastery Loop: • 🥉 ระดับพื้นฐาน (Bronze — Foundation): จำแนกอาชีพทางดนตรีออกเป็น 4 กลุ่มหลัก และระบุหน้าที่ของแต่ละอาชีพลงในใบกิจกรรม ผ13 ได้ถูกต้อง ≥ 80% • 🥈 ระดับมาตรฐาน (Silver — Core Standard): วิเคราะห์บทบาทของดนตรีในธุรกิจบันเทิง (การสร้างอารมณ์ร่วมในภาพยนตร์ การทำ Jingle จดจำแบรนด์ และการสร้างรายได้จากลิขสิทธิ์สตรีมมิง) ได้อย่างชัดเจน • 🥇 ระดับท้าทาย (Gold — Advanced Extension): สังเคราะห์แผนผังระบบนิเวศธุรกิจดนตรีและวางแผนบทบาทวิชาชีพสำหรับโปรเจกต์ผลิตสื่อเสียงในคาบที่ 14–15 2.3 การล็อกความเร็วและจังหวะเคาะ (Pulse & Tempo Synchronization): • ครูทำหน้าที่สังเกตการณ์เชิงรุก (Active Observation) ให้คำชี้แนะรายบุคคล (Individual Scaffolding) เพื่อให้นักเรียนรักษาความเร็วสม่ำเสมอตามจังหวะบีตมาตรฐาน",
      "3.1 การจัดคู่หูดนตรีร่วมบรรเลง (Buddy Co-Pilot Setup): • นักเรียนจับคู่ 20 คู่ (ทุกคนมีเครื่องประจำตัว 1:1) แบ่งบทบาทระหว่าง Melody Lead (ผู้บรรเลงหลัก) และ Rhythm Coach (ผู้คุมจังหวะและคอยเคาะช่วย) 3.2 การบรรเลงประสานและการวิเคราะห์ความแม่นยำ (Synchronized Rehearsal & Rhythm Check): • คู่บัดดี้ร่วมกันวิเคราะห์กรณีศึกษาในใบกิจกรรม ผ13 และเลือกสวมบทบาทวิชาชีพทางดนตรี (เช่น คนที่ 1 เป็น Music Producer & Sound Designer / คนที่ 2 เป็น Creative Director & Host) 3.3 การแลกเปลี่ยนฟีดแบ็กเชิงสร้างสรรค์ (Constructive Peer Feedback): • สลับบทบาทหน้าที่ และร่วมกันบันทึกจุดที่จังหวะยังแกว่งหรือสะดุดลงในใบกิจกรรมประจำแผน",
      "4.1 การมอบหมายภารกิจสร้างสรรค์ทางดนตรี (Creative Challenge Briefing): • ภารกิจ 'Phayao Sound Branding Pitch': คู่บัดดี้ออกแบบแนวคิดการใช้เสียงคาลิมบ้าคีย์ C ผสมเอกลักษณ์ล้านนา เพื่อทำเพลงประจำแบรนด์ (Audio Logo / Jingle) ส่งเสริมการท่องเที่ยวจังหวัดพะเยาหรือธุรกิจบันเทิงสร้างสรรค์ บันทึกลงในใบกิจกรรม ผ13 4.2 การรังสรรค์และทดลองบรรเลง (Inventive Rehearsal & Tryout): • คู่หูดนตรีร่วมกันออกแบบ ค้นคว้าแพทเทิร์นเสียง และทดลองบรรเลงในคีย์ C Major อย่างอิสระ"
     ]
