    "teach": {
     "title": "ขั้นสอน",
     "minutes": 38,
     "tag": "P - Practice (18 นาที) / A - Active Collaboration & Analysis (10 นาที) / C - Creative Challenge (10 นาที)",
     "items": [
      "2.1 การสาธิตจำลองทักษะและการดีดไร้เสียง (Modeling & Silent Air-Tap): • ครูสาธิตแบบอย่างท่าทางการวางมือประคองเครื่องทำมุม 45 องศา และการดีดลิ่มเสียงตามจังหวะเคาะ นักเรียนทำตามแบบจำลองไร้เสียง (Silent Air-Tap) เพื่อสร้างความคุ้นเคยของกล้ามเนื้อมือและประสาทสัมผัส 2.2 วงจรฝึกปฏิบัติปรับเหมาะ 3 ระดับ (3-Tier Differentiated Mastery Practice): นักเรียนวิเคราะห์บทบาทดนตรีตามยุคสมัย (ศ 2.2 ม.2/1) และฝึกพล็อตพิกัดอารมณ์เพลงทั้ง 3 เพลงลงในกราฟพิกัดอารมณ์ 2 มิติ (แกน X: ความรื่นรมย์ -5 ถึง +5 / แกน Y: พลังงานความตื่นตัว -5 ถึง +5) ตามวงจร 3-Tier Mastery Loop: • 🥉 ระดับพื้นฐาน (Bronze — Foundation): ระบุบทบาททางสังคมของเพลงทั้ง 3 ยุคสมัย และลงจุดพิกัด (X, Y) พร้อมเขียนคำบรรยายอารมณ์เพลงในใบกิจกรรม ผ16 ได้ครบถ้วน • 🥈 ระดับมาตรฐาน (Silver — Core Standard): วิเคราะห์เชื่อมโยงว่าความเร็ว (BPM) ความดัง-เบา และโหมดเสียง (Major/Minor) ส่งผลให้พิกัดตกอยู่ในแต่ละจตุภาคอย่างไร • 🥇 ระดับท้าทาย (Gold — Advanced Extension): เปรียบเทียบความเหมือนและความต่างของการใช้องค์ประกอบดนตรีเพื่อสื่ออารมณ์ในยุคอดีตกับยุคปัจจุบันได้อย่างลึกซึ้ง 2.3 การล็อกความเร็วและจังหวะเคาะ (Pulse & Tempo Synchronization): • ครูทำหน้าที่สังเกตการณ์เชิงรุก (Active Observation) ให้คำชี้แนะรายบุคคล (Individual Scaffolding) เพื่อให้นักเรียนรักษาความเร็วสม่ำเสมอตามจังหวะบีตมาตรฐาน",
      "3.1 การจัดคู่หูดนตรีร่วมบรรเลง (Buddy Co-Pilot Setup): • นักเรียนจับคู่ 20 คู่ (ทุกคนมีเครื่องประจำตัว 1:1) แบ่งบทบาทระหว่าง Melody Lead (ผู้บรรเลงหลัก) และ Rhythm Coach (ผู้คุมจังหวะและคอยเคาะช่วย) 3.2 การบรรเลงประสานและการวิเคราะห์ความแม่นยำ (Synchronized Rehearsal & Rhythm Check): • คู่บัดดี้แลกเปลี่ยนกราฟพิกัดอารมณ์ในใบกิจกรรม ผ16 เพื่อสังเกตว่าจุดพิกัดของตนเองและเพื่อนอยู่ในจตุภาคเดียวกันหรือต่างกันเพราะเหตุใด 3.3 การแลกเปลี่ยนฟีดแบ็กเชิงสร้างสรรค์ (Constructive Peer Feedback): • สลับบทบาทหน้าที่ และร่วมกันบันทึกจุดที่จังหวะยังแกว่งหรือสะดุดลงในใบกิจกรรมประจำแผน",
      "4.1 การมอบหมายภารกิจสร้างสรรค์ทางดนตรี (Creative Challenge Briefing): • ภารกิจ 'C-Major vs A-Minor Emotion Switcher': คู่บัดดี้ใช้คาลิมบ้าคีย์ C Major เครื่องเดิม ทดลองดีดทำนองสั้นบนคอร์ด C Major (ลิ่ม 1-3-5 ความเร็ว 90 BPM -> พิกัด +X, +Y สดใสรื่นเริง) แล้วเปลี่ยนมาดีดบนคอร์ดญาติ A Minor (ลิ่ม 6-1'-3' ความเร็ว 55 BPM -> พิกัด -X, -Y สงบขรึม/ซึ้ง) เพื่อพิสูจน์กลไกการเปลี่ยนอารมณ์เพลงด้วยตนเอง! 4.2 การรังสรรค์และทดลองบรรเลง (Inventive Rehearsal & Tryout): • คู่หูดนตรีร่วมกันออกแบบ ค้นคว้าแพทเทิร์นเสียง และทดลองบรรเลงในคีย์ C Major อย่างอิสระ"
     ]
    },
