      "1.1 การจุดประกายความสนใจและเชื่อมโยงโสตทักษะ (Spark Interest & Acoustic Phenomenon): • ครูเปิดเพลงลูกทุ่ง/พื้นบ้านยุคแผ่นเสียงครั่ง เทียบกับเพลงลูกทุ่ง/พื้นบ้านร่วมสมัยที่ผสมบีต Hip-Hop/Synth 1.2 การตั้งคำถามกระตุ้นคิดเชิงสืบเสาะ (Inquiry Driving Question): • คำถามกระตุ้นคิด (Driving Question): 'อะไรคือแรงผลักดันที่ทำให้ดนตรีเปลี่ยนโฉมไปในทุกทศวรรษ และทำไมคนต่างเจเนอเรชันหรือแม้แต่เพื่อนในห้องเดียวกัน จึงฟังเพลงเดียวกันแล้วรู้สึกไม่เหมือนกัน?' 1.3 การเตรียมความพร้อมอุปกรณ์รายบุคคล (Individual Readiness Check): • นักเรียนทั้ง 40 คนตรวจนับและจัดวางคาลิมบ้า 17 คีย์ประจำตัว (อัตราส่วน 1:1 ครบ 100%) บนผ้ารองประจำโต๊ะ พร้อมเปิดใช้งาน Smart Metronome บนแอป MusicSmart เพื่อเตรียมความพร้อมของสัญญาณจังหวะ"
